sp_widget.client_script:
api.controller = function($scope, $rootScope, $sce, $window) {
    var c = this;

    if (!c.data.enabled) {
        return;
    }

    c.visible = false;
    c.minimized = false;
    c.chatUrl = null;
    c.communication = null;

    var STORAGE_KEY = 'aes.communication.chat.state';

    restoreState();


    var unregisterOpen =
        $rootScope.$on('aes.communication.chat.open',
            function(event, data) {

                if (!data || !data.communication_id) {
                    return;
                }

                c.communication = data;

                c.visible = true;
                c.minimized = false;

                c.chatUrl = buildChatUrl(data);

                saveState();
            }
        );

    c.minimize = function() {
        c.minimized = true;

        saveState();
    };

    c.restore = function() {
        c.minimized = false;

        saveState();
    };

    c.close = function() {
        c.visible = false;
        c.minimized = false;
        c.chatUrl = null;
        c.communication = null;

        clearState();
    };

    function buildChatUrl(context) {
        var params = {
            sysparm_default_topic: c.data.agentChat.topic,
            sysparm_load_active_only: 'true',
            sysparm_page: 'aes_details',
            sysparm_aes_route: context.route,
            sysparm_aes_communication: context.communication_id,
            sysparm_aes_source: 'announcement',
            sysparm_branding_key: c.data.agentChat.brandingKey,
            sysparm_portal: 'aes_chat',
            sysparm_consumer_account_context: 'aes'
        };

        var query = [];

        angular.forEach(params, function(value, key) {
            if (value === undefined || value === null || value === '') {
                return;
            }

            query.push(encodeURIComponent(key) + '=' + encodeURIComponent(value));
        });

        return $sce.trustAsResourceUrl('/sn_va_web_client_app_embed.do?' + query.join('&'));
    }

    $scope.$on('$destroy', function() {
        unregisterOpen();
    });

    function saveState() {
        try {
            $window.sessionStorage.setItem(STORAGE_KEY,
                JSON.stringify({
                    visible: c.visible,
                    minimized: c.minimized,
                    communication: c.communication
                })
            );
        } catch (e) {
            // Não bloqueia o chat
        }
    }


    function restoreState() {
        try {
            var stored = $window.sessionStorage.getItem(STORAGE_KEY);

            if (!stored) {
                return;
            }

            var state = JSON.parse(stored);

            if (!state || !state.visible || !state.communication || !state.communication.communication_id) {
                return;
            }

            c.communication = state.communication;
            c.visible = true;
            c.minimized = !!state.minimized;

            c.chatUrl = buildChatUrl(c.communication);

        } catch (e) {
            clearState();
        }
    }


    function clearState() {
        try {
            $window.sessionStorage.removeItem(STORAGE_KEY);
        } catch (e) {
            // Ignore
        }
    }
};

sp_widget.css:
.aes-chat {
    position: fixed;
    left: 50%;
    bottom: 32px;
    transform: translateX(-50%);

    width: 420px;
    height: 620px;

    display: flex;
    flex-direction: column;

    background: #ffffff;
    border: 1px solid rgba(32, 36, 40, 0.12);
    border-radius: 16px;

    overflow: hidden;

    box-shadow:
        0 18px 50px rgba(0, 0, 0, 0.20),
        0 4px 14px rgba(0, 0, 0, 0.10);

    z-index: 1050;
}


/* ================================
   AES HEADER
   ================================ */

.aes-chat__header {
    height: 52px;
    min-height: 52px;

    display: flex;
    align-items: center;
    justify-content: space-between;

    padding: 0 10px 0 16px;

    background: #252A2E;
    color: #ffffff;
    user-select: none;
}

.aes-chat__drag-handle {
    cursor: grab;
}

.aes-chat__drag-handle.aes-dragging {
    cursor: grabbing;
}

.aes-chat__drag-handle:hover,
.aes-chat__drag-handle:focus {
    color: #B7F000;
}

.aes-chat__header-content {
    display: flex;
    align-items: center;

    min-width: 0;
    flex: 1;
}


.aes-chat__title {
    display: block;

    color: #ffffff;

    font-size: 14px;
    font-weight: 600;
    line-height: 1;

    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}


/* ================================
   CONTROLS
   ================================ */

.aes-chat__drag-handle {
    width: 28px;
    height: 34px;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    flex: 0 0 auto;

    margin-right: 6px;
    padding: 0;

    border: 0;
    background: transparent;

    color: #9EA5AA;

    font-size: 16px;

    cursor: grab;
}

.aes-chat__drag-handle:hover,
.aes-chat__drag-handle:focus {
    color: #B7F000;
    outline: none;
}

.aes-chat__drag-handle.aes-dragging {
    cursor: grabbing;
}

.aes-chat__controls {
    display: flex;
    align-items: center;

    gap: 2px;
    margin-left: 12px;
}


.aes-chat__control {
    width: 34px;
    height: 34px;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    padding: 0;

    border: 0;
    border-radius: 8px;

    background: transparent;
    color: #ffffff;

    font-size: 14px;

    cursor: pointer;

    transition:
        background-color 0.15s ease,
        color 0.15s ease;
}


.aes-chat__control:hover,
.aes-chat__control:focus {
    background: rgba(255, 255, 255, 0.10);
    color: #B7F000;

    outline: none;
}


/* ================================
   CHAT BODY
   ================================ */

.aes-chat__body {
    position: relative;
    flex: 1;
    min-height: 0;
    overflow: hidden;
    background: #ffffff;
}

.aes-chat__frame {
    position: absolute;

    top: -58px;
    left: 0;

    display: block;

    width: 100%;
    height: calc(100% + 58px);

    border: 0;
}

/* ================================
   MINIMIZED
   ================================ */

.aes-chat--minimized {
    width: 320px;
    height: 52px;
    transition:
        height 0.22s ease,
        width 0.22s ease;
}

.aes-chat__brand {
    width: 30px;
    height: 30px;

    display: flex;
    align-items: center;
    justify-content: center;

    margin-right: 9px;

    border-radius: 8px;

    background: rgba(183, 240, 0, 0.10);
}

.aes-chat__logo {
    display: block;

    width: 22px;
    height: 22px;

    object-fit: contain;
}

sp_widget.script:
(function() {

    data.enabled = gs.getProperty('x_733168_aes.agent_chat.enabled', 'false') == 'true';

    if (!data.enabled) {
        return;
    }

    data.agentChat = {
        topic: gs.getProperty('x_733168_aes.agent_chat.topic', ''),
        brandingKey: gs.getProperty('x_733168_aes.agent_chat.branding_key', '')
    };

})();
